body:
## Problem

Fixes #2112.

With PXN, the proxy thread of a relay process runs proxy operations posted by ranks in *other* processes. For those operations, NCCL core passes the originating rank's profiler context (`op->profilerContext` → `sub->profilerContext`) to `startEvent` for the ProxyOp, ProxyStep and NetPlugin events (`src/plugin/profiler.cc`). That pointer belongs to the other process's address space. The example plugin already handles this for ProxyOp: it checks `proxyOp.pid != pid` and records the event in the global detached pool without touching the context.

Commit 2433df27 (first shipped in v2.30.3) added a teardown guard at the top of `exampleProfilerStartEvent()`:

```cpp
if (__atomic_load_n(&ctx->finalizing, __ATOMIC_RELAXED)) {
```

This runs before the PXN check and dereferences the foreign context, so the relay process segfaults in the proxy thread (`ncclProxyProgress → ncclProfilerStartProxyOpEvent → exampleProfilerStartEvent`), as reported in #2112. The same read also hits ProxyStep and NetPlugin events whose parent is a detached PXN ProxyOp. v2.29.x did not have this read.

## Fix

In the example plugin only:
- Skip the up-front `finalizing` check for proxy events (ProxyOp, ProxyStep, NetPlugin).
- A ProxyOp posted by this process checks its context right after the PXN branch, so it behaves as before.
- ProxyStep and NetPlugin events check the context of their parent event via the existing `contextFromEventHandle()`, which returns NULL for detached PXN ProxyOps. For local operations this is the same context as before.

All other event types keep the check unchanged. `stopEvent` and `recordEventState` already derive the context from the event handle, so they were not affected.

## Testing

I can't run PXN here (it needs GPUDirect RDMA), so I wrote a small harness that drives the plugin exactly like NCCL core does for a PXN operation:
- it `dlopen`s `libnccl-profiler-example.so` and calls `ncclProfiler_v7.init()`;
- it then starts ProxyOp → ProxyStep → NetPlugin (IB QP) events with a foreign context (an unmapped page) and `proxyOp.pid = getpid()+1`;
- finally it records a state, stops the events, and finalizes.

```
master:  ProxyOp   startEvent(foreign ctx, pid=393752) ...
         Segmentation fault (exit 139)
this PR: ProxyOp   -> handle 0x7fbc41104010
         ProxyStep -> handle 0x7fbc41104060
         NetPlugin -> handle 0x7fbc411040a8
         RESULT: PASS (PXN events recorded as detached)
```

End to end, for non-PXN proxy events: 2x H200 over IB loopback (`NCCL_P2P_DISABLE=1 NCCL_SHM_DISABLE=1`), `NCCL_PROFILE_EVENT_MASK=4095`, `all_reduce_perf` and `alltoall_perf -c 1`, with the example plugin built from master and from this PR. Both runs have 0 data errors and exit cleanly, and the histograms of event names in the dumped traces are identical (17 and 18 distinct event types, including ProxyOp/ProxyStep states and KernelCh).

<details><summary>Harness (pxn_profiler_harness.cc)</summary>

```cpp
// Drives the example profiler plugin the way NCCL core does for a PXN proxy operation: the proxy
// thread of the relay process starts ProxyOp / ProxyStep / NetPlugin events with the *originating*
// process's profiler context and pid. That context pointer is not valid in this process; here it
// is a page that has been unmapped, so any dereference faults.
//
// Build: g++ -I<nccl>/plugins/profiler/example/nccl pxn_profiler_harness.cc -ldl -o pxn_profiler_harness
// Usage: pxn_profiler_harness <path to libnccl-profiler-example.so>
#include <dlfcn.h>
#include <stdio.h>
#include <sys/mman.h>
#include <unistd.h>
#include <stdint.h>
#include <stddef.h>
#include "err.h"
#include "profiler.h"
#include "profiler_net.h"
#include "net_ib_v1.h"

static void logfn(ncclDebugLogLevel, unsigned long, const char*, int, const char*, ...) {}

int main(int argc, char** argv) {
  if (argc < 2) { fprintf(stderr, "usage: %s <libnccl-profiler-example.so>\n", argv[0]); return 2; }
  void* lib = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL);
  if (!lib) { fprintf(stderr, "dlopen: %s\n", dlerror()); return 2; }
  ncclProfiler_v7_t* prof = (ncclProfiler_v7_t*)dlsym(lib, "ncclProfiler_v7");
  if (!prof) { fprintf(stderr, "dlsym ncclProfiler_v7: %s\n", dlerror()); return 2; }

  // This process's own communicator, so the plugin is initialized as it would be in the relay.
  void* localCtx = NULL;
  int mask = 4095;
  if (prof->init(&localCtx, 0x1234, &mask, "harness", 2, 4, 1, logfn) != ncclSuccess || !localCtx) {
    fprintf(stderr, "init failed\n"); return 2;
  }

  // The originating process's context pointer: guaranteed unmapped here.
  long pg = sysconf(_SC_PAGESIZE);
  void* foreignCtx = mmap(NULL, pg, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
  munmap(foreignCtx, pg);
  void* foreignTask = (char*)foreignCtx + 64;  // the originating process's task event handle

  ncclProfilerEventDescr_v7_t d = {};
  d.type = ncclProfileProxyOp;
  d.parentObj = foreignTask;
  d.rank = 0;
  d.proxyOp.pid = getpid() + 1;  // posted by another process
  d.proxyOp.channelId = 0;
  d.proxyOp.peer = 2;
  d.proxyOp.nSteps = 4;
  d.proxyOp.chunkSize = 131072;
  d.proxyOp.isSend = 1;
  void* opHandle = NULL;
  printf("ProxyOp   startEvent(foreign ctx, pid=%d) ...\n", d.proxyOp.pid); fflush(stdout);
  if (prof->startEvent(foreignCtx, &opHandle, &d) != ncclSuccess) return 1;
  printf("  -> handle %p\n", opHandle);

  ncclProfilerEventDescr_v7_t s = {};
  s.type = ncclProfileProxyStep;
  s.parentObj = opHandle;
  s.rank = 0;
  s.proxyStep.step = 0;
  void* stepHandle = NULL;
  printf("ProxyStep startEvent(foreign ctx) ...\n"); fflush(stdout);
  if (prof->startEvent(foreignCtx, &stepHandle, &s) != ncclSuccess) return 1;
  printf("  -> handle %p\n", stepHandle);

  ncclProfilerNetIbDescr_v1_t ib = {};
  ib.type = ncclProfileQp;
  ib.qp.device = 0; ib.qp.wr_id = 1; ib.qp.opcode = 0; ib.qp.qpNum = 42; ib.qp.length = 131072;
  ncclProfilerEventDescr_v7_t n = {};
  n.type = ncclProfileNetPlugin;
  n.parentObj = stepHandle;
  n.rank = 0;
  n.netPlugin.id = NCCL_PROFILER_NET_TYPE_IB | NCCL_PROFILER_NET_IB_VER;
  n.netPlugin.data = &ib;
  void* netHandle = NULL;
  printf("NetPlugin startEvent(foreign ctx) ...\n"); fflush(stdout);
  if (prof->startEvent(foreignCtx, &netHandle, &n) != ncclSuccess) return 1;
  printf("  -> handle %p\n", netHandle);

  ncclProfilerEventStateArgs_v7_t a = {};
  if (stepHandle) prof->recordEventState(stepHandle, ncclProfilerProxyStepSendWait, &a);
  if (netHandle) prof->stopEvent(netHandle);
  if (stepHandle) prof->stopEvent(stepHandle);
  if (opHandle) prof->stopEvent(opHandle);
  prof->finalize(localCtx);

  bool ok = opHandle && stepHandle && netHandle;
  printf("RESULT: %s (PXN events %s)\n", ok ? "PASS" : "FAIL", ok ? "recorded as detached" : "dropped");
  return ok ? 0 : 1;
}
```

Build: `g++ -I plugins/profiler/example/nccl pxn_profiler_harness.cc -Wl,--no-as-needed -lcudart -ldl`
</details>

## Problem

`ncclCommRegister()` on a buffer that contains CPU-backed segments (e.g. `cudaHostAlloc` memory or cuMem host allocations, with cuMem enabled) returns `ncclSuccess` without registering it, but `ncclRegister()` returns early on that path without writing `*handle`. The other skip path in `ncclCommRegister()` (`NCCL_LOCAL_REGISTER=0` / P2P CE memcpy) sets `*handle = NULL`.

The caller's handle is left uninitialized. Passing it to `ncclCommDeregister()` then fails with `ncclInvalidUsage` ("Deregister: Could not find handle"), or it could match a stale registration. NCCL's internal callers of `ncclCommGraphRegister()` pre-initialize their handle to NULL, so only applications calling the public API are affected.

## Fix

Set `*handle = NULL` before returning on the CPU-memory skip path. `ncclCommDeregister(comm, NULL)` is already a no-op.

## Testing

H200, single-rank comm, cuMem enabled (default). The handle is pre-set to `0xdeadbeef` to stand in for an uninitialized variable:

```
master:  ncclCommRegister(host buffer) -> no error, handle=0xdeadbeef
         ncclCommDeregister(handle)    -> invalid usage
this PR: ncclCommRegister(host buffer) -> no error, handle=(nil)
         ncclCommDeregister(handle)    -> no error
```

<details><summary>Test program (reg_host_handle.cu)</summary>

```cuda
// Repro: ncclCommRegister() returns ncclSuccess for a CPU-backed buffer without writing *handle.
#include <cuda_runtime.h>
#include <nccl.h>
#include <stdio.h>

int main() {
  ncclComm_t comm;
  int dev = 0;
  if (ncclCommInitAll(&comm, 1, &dev) != ncclSuccess) return 2;
  void* host;
  cudaHostAlloc(&host, 4 << 20, cudaHostAllocDefault);
  void* handle = (void*)0xdeadbeef;  // what an uninitialized stack variable may hold
  ncclResult_t r = ncclCommRegister(comm, host, 4 << 20, &handle);
  printf("ncclCommRegister(host buffer) -> %s, handle=%p\n", ncclGetErrorString(r), handle);
  r = ncclCommDeregister(comm, handle);
  printf("ncclCommDeregister(handle)    -> %s\n", ncclGetErrorString(r));
  bool ok = handle == NULL && r == ncclSuccess;
  printf("RESULT: %s\n", ok ? "PASS" : "FAIL");
  cudaFreeHost(host);
  ncclCommDestroy(comm);
  return ok ? 0 : 1;
}
```
</details>

## Problem

With `NCCL_P2P_USE_CUDA_MEMCPY=1`, `p2pRecvConnect()` always imports the sender proxy's SHM segment into `resources->desc` (`ncclShmImportShareableBuffer`). `p2pRecvFree()` closes it only in the legacy (non-cuMem) branch, so with cuMem enabled (the default) the importer's mapping and imported allocation handle are never released. Every communicator leaks host memory and VA mappings. When cuMem is on but cuMem host is off, the import falls back to `/dev/shm`, and that mmap also leaks.

`shmRecvFree()` in the SHM transport already closes its imported descriptor unconditionally; the P2P receive side was the only one that didn't.

## Fix

Close the descriptor whenever CE memcpy mode imported it, whether or not cuMem is enabled. `ncclShmIpcClose()` picks the matching cuMem or legacy path from the descriptor, and it is a no-op for a zeroed descriptor (recv resources are calloc'ed).

## Testing

2x H200, one process, `NCCL_SHM_DISABLE=1`. The test loops `ncclCommInitAll` → 4 MB AllReduce → `ncclCommDestroy` and prints `/proc/self/maps` lines and VmRSS after each cycle.

| `NCCL_P2P_USE_CUDA_MEMCPY=1` with | master (2.32.3-1) | this PR |
|---|---|---|
| defaults (cuMem + cuMem host) | maps 388 → 993, VmRSS 791 MB → 1.92 GB over 12 cycles (~+50 maps, ~+100 MB per cycle) | maps flat at 286, VmRSS plateaus ~805 MB |
| `NCCL_CUMEM_HOST_ENABLE=0` | maps 333 → 765 over 10 cycles | flat at 284 |
| `NCCL_CUMEM_ENABLE=0` | flat at 274 | flat at 274 (unchanged path) |
| control: default P2P (no CE memcpy) | flat at 269 | — |

Correctness with CE memcpy mode, cuMem on and off: `all_reduce_perf` and `sendrecv_perf -c 1` (8 B – 64 MB) have 0 errors.

<details><summary>Test program (comm_cycle_leak.cu)</summary>

```cuda
// Repeated communicator init / allreduce / destroy on N GPUs in one process, printing the
// process mapping count and RSS after each cycle, to detect per-communicator resource leaks.
// Usage: comm_cycle_leak <ngpus> <cycles>
#include <cuda_runtime.h>
#include <nccl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <vector>

static long mapsCount() {
  FILE* f = fopen("/proc/self/maps", "r");
  long n = 0; int c;
  while ((c = fgetc(f)) != EOF) n += c == '\n';
  fclose(f);
  return n;
}

static long statusKb(const char* key) {
  FILE* f = fopen("/proc/self/status", "r");
  char line[256]; long v = -1;
  while (fgets(line, sizeof(line), f)) {
    if (strncmp(line, key, strlen(key)) == 0) { v = atol(line + strlen(key) + 1); break; }
  }
  fclose(f);
  return v;
}

#define CHECK(cmd) do { ncclResult_t r = cmd; if (r != ncclSuccess) { \
  printf("NCCL error %s:%d '%s'\n", __FILE__, __LINE__, ncclGetErrorString(r)); return 1; } } while (0)

int main(int argc, char** argv) {
  int n = argc > 1 ? atoi(argv[1]) : 2;
  int cycles = argc > 2 ? atoi(argv[2]) : 20;
  const size_t count = 1 << 20;
  std::vector<int> devs(n);
  std::vector<float*> bufs(n);
  std::vector<cudaStream_t> streams(n);
  for (int i = 0; i < n; i++) {
    devs[i] = i;
    cudaSetDevice(i);
    cudaMalloc(&bufs[i], count * sizeof(float));
    cudaStreamCreate(&streams[i]);
  }
  for (int it = 0; it < cycles; it++) {
    std::vector<ncclComm_t> comms(n);
    CHECK(ncclCommInitAll(comms.data(), n, devs.data()));
    CHECK(ncclGroupStart());
    for (int i = 0; i < n; i++) {
      CHECK(ncclAllReduce(bufs[i], bufs[i], count, ncclFloat, ncclSum, comms[i], streams[i]));
    }
    CHECK(ncclGroupEnd());
    for (int i = 0; i < n; i++) { cudaSetDevice(i); cudaStreamSynchronize(streams[i]); }
    for (int i = 0; i < n; i++) CHECK(ncclCommDestroy(comms[i]));
    printf("cycle %3d maps %6ld VmRSS %8ld kB VmPin %6ld kB\n", it, mapsCount(), statusKb("VmRSS"),
           statusKb("VmPin"));
    fflush(stdout);
  }
  return 0;
}
```
</details>

## Summary

Do not enable profiler proxy events when proxy initialization fails. This prevents `SaveProxyProfiler()` from dereferencing a null proxy pool after `/dev/shm` allocation failure.

## Validation

- Profiler v6 requesting `ncclProfileColl | ncclProfileKernelCh`, two T4 ranks.
- 64 MiB `/dev/shm`: previously segfaulted in `ncclLocalOpAppend`; now logs allocation warnings and exits 0.
- 1 GiB `/dev/shm`: exits 0.

